#include <iostream>
#include <sstream>
#include <cstring>
#include <iomanip>

// POD-compatible fixed-size record for safe raw binary I/O
struct ClientRecord {
    int accountNumber{0};
    char name[20]{""};
    double balance{0.0};
};

int main() {
    // Use stringstream with binary mode to simulate disk storage deterministically
    std::stringstream fileStream(std::ios::in | std::ios::out | std::ios::binary);

    // 1. Prepare and write record
    ClientRecord writeRecord;
    writeRecord.accountNumber = 101;
    std::strncpy(writeRecord.name, "Alice Smith", sizeof(writeRecord.name) - 1);
    writeRecord.balance = 254.75;

    fileStream.write(reinterpret_cast<const char*>(&writeRecord), sizeof(ClientRecord));

    // 2. Reposition 'get' pointer to beginning for sequential/random read
    fileStream.seekg(0, std::ios::beg);

    // 3. Read record back
    ClientRecord readRecord;
    fileStream.read(reinterpret_cast<char*>(&readRecord), sizeof(ClientRecord));

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Account: " << readRecord.accountNumber << "\n"
              << "Name:    " << readRecord.name << "\n"
              << "Balance: $" << readRecord.balance << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>

void runFileMatch(std::istream& inOldMaster, std::istream& inTransaction, std::ostream& outNewMaster) {
    int masterAcc = 0;
    std::string masterName;
    double masterBal = 0.0;
    bool hasMaster = static_cast<bool>(inOldMaster >> masterAcc >> masterName >> masterBal);

    int transAcc = 0;
    double transAmount = 0.0;
    bool hasTrans = static_cast<bool>(inTransaction >> transAcc >> transAmount);

    while (hasMaster && hasTrans) {
        if (masterAcc == transAcc) {
            masterBal += transAmount;
            hasTrans = static_cast<bool>(inTransaction >> transAcc >> transAmount);
            // Note: If multiple transactions exist for the same account, this loop continues accumulating
            while (hasTrans && masterAcc == transAcc) {
                masterBal += transAmount;
                hasTrans = static_cast<bool>(inTransaction >> transAcc >> transAmount);
            }
            outNewMaster << masterAcc << " " << masterName << " " << std::fixed << std::setprecision(2) << masterBal << "\n";
            hasMaster = static_cast<bool>(inOldMaster >> masterAcc >> masterName >> masterBal);
        } else if (masterAcc < transAcc) {
            outNewMaster << masterAcc << " " << masterName << " " << std::fixed << std::setprecision(2) << masterBal << "\n";
            hasMaster = static_cast<bool>(inOldMaster >> masterAcc >> masterName >> masterBal);
        } else { // masterAcc > transAcc
            std::cout << "Unmatched transaction record for account number " << transAcc << "\n";
            hasTrans = static_cast<bool>(inTransaction >> transAcc >> transAmount);
        }
    }

    // Flush remaining master records
    while (hasMaster) {
        outNewMaster << masterAcc << " " << masterName << " " << std::fixed << std::setprecision(2) << masterBal << "\n";
        hasMaster = static_cast<bool>(inOldMaster >> masterAcc >> masterName >> masterBal);
    }

    // Report any trailing unmatched transactions
    while (hasTrans) {
        std::cout << "Unmatched transaction record for account number " << transAcc << "\n";
        hasTrans = static_cast<bool>(inTransaction >> transAcc >> transAmount);
    }
}

int main() {
    // Simulated oldmast.dat (Exercise 14.7)
    std::istringstream oldMaster(
        "100 Alan_Jones 348.17\n"
        "300 Mary_Smith 27.19\n"
        "500 Sam_Sharp 0.00\n"
        "700 Suzy_Green -14.22\n"
    );

    // Simulated trans.dat (Exercise 14.7)
    std::istringstream transaction(
        "100 27.14\n"
        "300 62.11\n"
        "400 100.56\n"
        "900 82.17\n"
    );

    std::ostringstream newMaster;
    runFileMatch(oldMaster, transaction, newMaster);

    std::cout << "--- New Master File ---\n" << newMaster.str();
    return 0;
}
